  {
    id: 'booking', icon: '📅', title: 'Đặt lịch không bị trùng khung giờ', goal: 'Business rule · unique constraint · locking · expiry', roles: ['Java / .NET', 'Frontend / Fullstack', 'BA / PM / PO'],
    scenario: 'Hai bệnh nhân cùng chọn một bác sĩ lúc 9:00. Mỗi người mất vài giây điền form; request có thể đến gần như đồng thời hoặc người giữ chỗ bỏ ngang.',
    outcome: 'Một khung giờ chỉ được xác nhận cho một bệnh nhân và chỗ giữ tạm tự hết hạn.',
    steps: [
      { id: 'model', kind: 'DOMAIN MODEL · BƯỚC 1', title: 'Mô hình hóa trạng thái lịch hẹn', what: 'Domain model biểu diễn khái niệm và quy tắc nghiệp vụ bằng object/state có ý nghĩa với sản phẩm.', role: 'Appointment có slot, patient, status HELD/CONFIRMED/CANCELLED, holdExpiresAt và lịch sử chuyển trạng thái.', why: 'Một boolean booked không phân biệt chỗ đang giữ, đã xác nhận hay đã hủy; trạng thái mơ hồ dẫn tới xử lý lỗi.', how: 'Vẽ state transition hợp lệ, ví dụ HELD → CONFIRMED hoặc HELD → EXPIRED; mọi transition kiểm tra trạng thái hiện tại.', tradeoff: 'State machine rõ hơn nhưng cần định nghĩa ai có quyền chuyển trạng thái và xử lý các event đến trễ.', english: 'I model the appointment lifecycle explicitly so a temporary hold is different from a confirmed booking.', path: '/business-domains' },
      { id: 'atomic', kind: 'DATABASE · BƯỚC 2', title: 'Unique constraint và atomic reservation', what: 'Unique constraint là quy tắc toàn vẹn do DB đảm bảo; atomic update làm thao tác kiểm tra và ghi diễn ra như một bước không thể chen ngang.', role: 'DB là nơi cuối cùng ngăn hai request cùng chiếm một slot, dù ứng dụng chạy nhiều instance.', why: 'Kiểm tra “slot còn trống?” trong Java rồi insert sau đó không an toàn khi hai request cùng chạy.', how: 'Tạo unique key cho slot đã confirm hoặc conditional update slot status; bắt duplicate-key/conflict và trả HTTP 409.', tradeoff: 'Chọn schema/constraint theo cách lưu slot và cancellation; lock quá rộng làm giảm khả năng đặt lịch đồng thời.', english: 'The database constraint is the final protection against two requests booking the same slot.', path: '/java/backend/sql' },
      { id: 'hold', kind: 'TIMEOUT · BƯỚC 3', title: 'Giữ chỗ có hạn và giải phóng an toàn', what: 'Expiring hold là reservation tạm có thời hạn, sau đó được giải phóng nếu người dùng không hoàn tất.', role: 'Giữ slot trong lúc người dùng thanh toán; job hoặc request tiếp theo dọn hold hết hạn.', why: 'Giữ chỗ vô thời hạn làm lịch trống biến mất; giải phóng chỉ dựa trên một scheduler có thể bị trễ khi job lỗi.', how: 'Lưu holdExpiresAt theo UTC; mọi thao tác xác nhận kiểm tra deadline trong transaction; scheduler chỉ là cơ chế dọn phụ trợ.', tradeoff: 'Đồng hồ máy lệch và payment callback tới trễ cần được xử lý bằng thời điểm chuẩn và state transition hợp lệ.', english: 'A hold expires after a defined period, and confirmation checks the expiry inside a transaction.', path: '/java/backend/design' },
