    deliverable: { title: 'Vẽ luồng đặt lịch khám', tasks: ['Định nghĩa Appointment state và transition.', 'Vẽ hai request tranh cùng một slot.', 'Chọn unique constraint hoặc atomic update và mô tả response conflict.', 'Nêu cách giải phóng slot khi payment timeout.'], check: 'Bạn giải thích được vì sao kiểm tra ở frontend hoặc một lần SELECT không thể bảo vệ slot trước concurrent requests.' },
